// ============================================================ LEAVE IT OPEN
// A colossal hand made of every format lifts Rin up through the cloud sea at
// dawn. Walking up its finger plays the melody, step by step. At the tip, a
// second hand — a human one — reaches down. Hold E, and close the gap.
const THEME = ['E5', 'G5', 'C6', 'B5', 'G5', 'D5', 'C6', 'A5', 'E5', 'A5', 'F5', 'C5', 'G5', 'E5', 'C5', 'F5', 'A5', 'C6', 'D6', 'C6', 'G5', 'B5', 'C6', 'E6'];
