const DAWN = (() => { const bars = {}, pad = ['C3+G3+E4', 'A2+E3+C4', 'F2+C3+A3', 'G2+D3+B3']; const A = pad.map((c, i) => { bars['a' + i] = { pad: `${c} - - - - - - - - - - - - - - -`, str: i % 2 ? `${c.replace(/3/g, '4').replace(/2/g, '3')} - - - - - - - . . . . . . . .` : '. . . . . . . . . . . . . . . .', pno: `${c.split('+')[0]} . . . ${c.split('+')[1]} . . . ${c.split('+')[2]} . . . ${c.split('+')[1]} . . .`, bell: i === 3 ? '. . . . . . . . G6 . . . . . . .' : '. . . . . . . . . . . . . . . .' }; return 'a' + i; }); return { bpm: 70, gain: 1, reverb: 0.7, start: 'A', tracks: { pad: { inst: 'pad', vol: 0.55, send: 0.8 }, str: { inst: 'strings', vol: 0.5, send: 0.7, layer: 1 }, pno: { inst: 'piano', vol: 0.45, send: 0.6, layer: 2 }, bell: { inst: 'bell', vol: 0.35, send: 0.8, layer: 3 } }, bars, sections: { A }, next: { A: 'A' } }; })();

